package com.example.demo.search;

import org.springframework.data.jpa.domain.Specification;
import org.springframework.data.jpa.repository.JpaSpecificationExecutor;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.Id;

import java.util.List;

@Entity
class Product {

    @Id
    @GeneratedValue
    private Long id;

    private String name;

    private String category;

    private Integer price;

    // getter/setter省略
}

interface ProductRepository extends JpaRepository<Product, Long>, JpaSpecificationExecutor<Product> {
}

class ProductSpecifications {

    public static Specification<Product> nameContains(String keyword) {
        return (root, query, cb) -> keyword == null || keyword.isBlank()
                ? null
                : cb.like(root.get("name"), "%" + keyword + "%");
    }

    public static Specification<Product> categoryEquals(String category) {
        return (root, query, cb) -> category == null || category.isBlank()
                ? null
                : cb.equal(root.get("category"), category);
    }

    public static Specification<Product> priceLessThanOrEqual(Integer priceMax) {
        return (root, query, cb) -> priceMax == null ? null : cb.le(root.get("price"), priceMax);
    }
}

@RestController
@RequestMapping("/api/products")
class ProductSearchController {

    private final ProductRepository productRepository;

    ProductSearchController(ProductRepository productRepository) {
        this.productRepository = productRepository;
    }

    @GetMapping
    public List<Product> search(@RequestParam(required = false) String keyword,
                                @RequestParam(required = false) String category,
                                @RequestParam(required = false) Integer priceMax) {
        Specification<Product> spec = Specification
                .where(ProductSpecifications.nameContains(keyword))
                .and(ProductSpecifications.categoryEquals(category))
                .and(ProductSpecifications.priceLessThanOrEqual(priceMax));

        return productRepository.findAll(spec);
    }
}

package com.example.demo.config;

