package com.example.demo.lock;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.Id;
import jakarta.persistence.Version;

@Entity
class Account {

    @Id
    @GeneratedValue
    private Long id;

    private Long balance;

    @Version
    private Long version;

    // getter/setter省略
}

interface AccountRepository extends JpaRepository<Account, Long> {
}

@Service
class AccountService {

    private final AccountRepository accountRepository;

    AccountService(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    @Transactional
    public void withdraw(Long accountId, long amount) {
        try {
            Account account = accountRepository.findById(accountId)
                    .orElseThrow(() -> new IllegalArgumentException("account not found"));
            if (account.getBalance() < amount) {
                throw new IllegalStateException("insufficient balance");
            }
            account.setBalance(account.getBalance() - amount);
        } catch (ObjectOptimisticLockingFailureException e) {
            // 競合した場合のリトライやエラー変換はここで行う
            throw e;
        }
    }
}

package com.example.demo.stock;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.Id;
import jakarta.persistence.LockModeType;

@Entity
class Stock {

    @Id
    @GeneratedValue
    private Long id;

    private String sku;

    private Long quantity;

    // getter/setter省略
}

interface StockRepository extends JpaRepository<Stock, Long> {

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select s from Stock s where s.sku = :sku")
    Stock findBySkuForUpdate(String sku);
}

@Service
class StockService {

    private final StockRepository stockRepository;

    StockService(StockRepository stockRepository) {
        this.stockRepository = stockRepository;
    }

    @Transactional
    public void reserve(String sku, long quantity) {
        Stock stock = stockRepository.findBySkuForUpdate(sku);
        if (stock.getQuantity() < quantity) {
            throw new IllegalStateException("no stock");
        }
        stock.setQuantity(stock.getQuantity() - quantity);
    }
}

