package com.example.demo.jsoncolumn;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.persistence.AttributeConverter;
import jakarta.persistence.Converter;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.Id;

import java.util.Map;

@Converter
public class JsonMapConverter implements AttributeConverter<Map<String, Object>, String> {

    private static final ObjectMapper objectMapper = new ObjectMapper();

    @Override
    public String convertToDatabaseColumn(Map<String, Object> attribute) {
        if (attribute == null) return null;
        try {
            return objectMapper.writeValueAsString(attribute);
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("failed to serialize json", e);
        }
    }

    @Override
    public Map<String, Object> convertToEntityAttribute(String dbData) {
        if (dbData == null) return null;
        try {
            return objectMapper.readValue(dbData, Map.class);
        } catch (Exception e) {
            throw new IllegalArgumentException("failed to deserialize json", e);
        }
    }
}

@Entity
class JsonLog {

    @Id
    @GeneratedValue
    private Long id;

    private String type;

    @jakarta.persistence.Convert(converter = JsonMapConverter.class)
    private Map<String, Object> payload;

    // getter/setter省略
}

package com.example.demo.enumcode;

import jakarta.persistence.AttributeConverter;
import jakarta.persistence.Converter;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.Id;

enum OrderStatus {
    NEW("N"),
    PAID("P"),
    CANCELED("C");

    private final String code;

    OrderStatus(String code) { this.code = code; }

    public String getCode() { return code; }

    public static OrderStatus fromCode(String code) {
        for (OrderStatus s : values()) {
            if (s.code.equals(code)) return s;
        }
        throw new IllegalArgumentException("unknown code: " + code);
    }
}

@Converter(autoApply = true)
class OrderStatusConverter implements AttributeConverter<OrderStatus, String> {

    @Override
    public String convertToDatabaseColumn(OrderStatus attribute) {
        return attribute == null ? null : attribute.getCode();
    }

    @Override
    public OrderStatus convertToEntityAttribute(String dbData) {
        return dbData == null ? null : OrderStatus.fromCode(dbData);
    }
}

@Entity
class OrderEntity {

    @Id
    @GeneratedValue
    private Long id;

    private OrderStatus status;

    // getter/setter省略
}

package com.example.demo.tx;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {

    private final OrderRepository orderRepository;
    private final PaymentGateway paymentGateway;

    public OrderService(OrderRepository orderRepository, PaymentGateway paymentGateway) {
        this.orderRepository = orderRepository;
        this.paymentGateway = paymentGateway;
    }

    @Transactional
    public void placeOrder(PlaceOrderCommand command) {
        Order order = new Order(command.getUserId(), command.getItems());
        orderRepository.save(order);

        // 外部APIの失敗で例外が投げられた場合、注文登録もロールバックされる
        paymentGateway.charge(order.getId(), order.getTotalAmount());

        order.markPaid();
    }
}

// OrderRepository, PaymentGateway, PlaceOrderCommand, Order は適宜定義

