package com.example.demo.resttemplate;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.client.DefaultResponseErrorHandler;
import org.springframework.web.client.RestTemplate;

import java.io.IOException;

@Configuration
public class RestTemplateConfig {

    @Bean
    public RestTemplate restTemplate() {
        RestTemplate restTemplate = new RestTemplate();
        restTemplate.setErrorHandler(new DefaultResponseErrorHandler() {
            @Override
            public void handleError(ClientHttpResponse response) throws IOException {
                if (response.getStatusCode().series() == HttpStatus.Series.SERVER_ERROR) {
                    // 5xxはそのまま例外
                    super.handleError(response);
                }
                // 4xxは独自例外に変換するなど
            }
        });
        return restTemplate;
    }

    public void postExample(RestTemplate restTemplate) {
        ResponseEntity<String> res = restTemplate.postForEntity("https://api.example.com/pay", new Object(), String.class);
        if (res.getStatusCode() != HttpStatus.OK) {
            throw new IllegalStateException("payment failed: " + res.getStatusCode());
        }
    }
}

