package com.example.demo.health;

import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.stereotype.Component;

import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.SQLException;

@Component
public class CompositeHealthIndicator implements HealthIndicator {

    private final DataSource dataSource;
    private final RedisPingClient redisPingClient;

    public CompositeHealthIndicator(DataSource dataSource, RedisPingClient redisPingClient) {
        this.dataSource = dataSource;
        this.redisPingClient = redisPingClient;
    }

    @Override
    public Health health() {
        Health.Builder builder = Health.up();
        // DB
        try (Connection c = dataSource.getConnection()) {
            if (!c.isValid(2)) {
                builder.down().withDetail("db", "invalid");
            } else {
                builder.withDetail("db", "ok");
            }
        } catch (SQLException e) {
            builder.down(e).withDetail("db", "error");
        }
        // Redis
        try {
            boolean ok = redisPingClient.ping();
            builder.withDetail("redis", ok ? "ok" : "ng");
            if (!ok) builder.down();
        } catch (Exception e) {
            builder.down(e).withDetail("redis", "error");
        }
        return builder.build();
    }
}

// RedisPingClientは"PING"を投げて true/false を返す簡易クライアントとして別途定義

