package com.example.demo.range;

import org.springframework.core.io.InputStreamResource;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;

import java.io.ByteArrayInputStream;

@RestController
public class RangeDownloadController {

    @GetMapping("/api/videos/sample")
    public ResponseEntity<InputStreamResource> getVideo(@RequestHeader(value = "Range", required = false) String rangeHeader) {
        byte[] all = new byte[1024 * 1024]; // 実際はファイルから読み込み
        int from = 0;
        int to = all.length - 1;
        if (rangeHeader != null && rangeHeader.startsWith("bytes=")) {
            String[] parts = rangeHeader.substring(6).split("-");
            from = Integer.parseInt(parts[0]);
            if (parts.length > 1 && !parts[1].isBlank()) {
                to = Integer.parseInt(parts[1]);
            }
        }
        int length = to - from + 1;
        ByteArrayInputStream input = new ByteArrayInputStream(all, from, length);
        HttpHeaders headers = new HttpHeaders();
        headers.add(HttpHeaders.CONTENT_RANGE, "bytes " + from + "-" + to + "/" + all.length);
        return ResponseEntity.status(HttpStatus.PARTIAL_CONTENT)
                .headers(headers)
                .contentLength(length)
                .contentType(MediaType.valueOf("video/mp4"))
                .body(new InputStreamResource(input));
    }
}

