package com.example.demo.taskdecorator;

import org.slf4j.MDC;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.task.TaskDecorator;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

@Configuration
public class MdcTaskDecoratorConfig {

    @Bean
    public ThreadPoolTaskExecutor mdcExecutor() {
        ThreadPoolTaskExecutor ex = new ThreadPoolTaskExecutor();
        ex.setTaskDecorator(mdcTaskDecorator());
        ex.initialize();
        return ex;
    }

    @Bean
    public TaskDecorator mdcTaskDecorator() {
        return runnable -> {
            var contextMap = MDC.getCopyOfContextMap();
            return () -> {
                if (contextMap != null) MDC.setContextMap(contextMap);
                try { runnable.run(); } finally { MDC.clear(); }
            };
        };
    }
}

package com.example.demo.unique;

