package com.example.demo.errorview;

import jakarta.servlet.http.HttpServletRequest;
import org.springframework.boot.web.error.ErrorAttributeOptions;
import org.springframework.boot.web.servlet.error.ErrorAttributes;
import org.springframework.boot.web.servlet.error.ErrorController;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.RequestMapping;

import java.util.Map;

@Controller
public class MixedErrorController implements ErrorController {

    private final ErrorAttributes errorAttributes;

    public MixedErrorController(ErrorAttributes errorAttributes) {
        this.errorAttributes = errorAttributes;
    }

    @RequestMapping(value = "/error", produces = MediaType.TEXT_HTML_VALUE)
    public String errorHtml(HttpServletRequest request, Model model) {
        Map<String, Object> attrs = errorAttributes.getErrorAttributes(null, ErrorAttributeOptions.defaults());
        model.addAttribute("attrs", attrs);
        return "error/custom"; // templates/error/custom.html
    }

    @RequestMapping(value = "/error", produces = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<Map<String, Object>> errorJson(HttpServletRequest request) {
        Map<String, Object> attrs = errorAttributes.getErrorAttributes(null, ErrorAttributeOptions.defaults());
        int status = (int) attrs.getOrDefault("status", 500);
        return ResponseEntity.status(status).body(attrs);
    }
}
